_txt_novos = json.dumps({n_: {k_: (core.get(n_) or {}).get(k_) for k_ in ("verdict", "estatuto", "scope", "limites", "diz", "nao_diz", "erratas")} for n_ in list(DL.REGISTROS_FUNCAO) + RNNEW}, ensure_ascii=False)
