_MARCAS_NOVAS = r'''TW406 = "A massa derivada e a identidade definida"; TW406E = "The derived mass and the defined identity"; TI406 = "A identidade"; TI406E = "The identity"
TJ405 = "Jo 8,32 e a projeção transversal da Meia-Nat"; TJ405E = "John 8:32 and the transverse projection of the Half-Nat"
MARCAS406_PT = [TW406, "O que entra.", "A moldura: o que fechou e o que entra.", "A Ponte da Massa.", "Massa = tensão pura.", "A lei do diminuto.", "A Tônica do Hamiltoniano.", "O Ponto Zero do Psíon.", "O Disco de Euler.", "Observador = terminal.", "A pedra Identidade.", "Erratas ao lado (v406).", "Limites.", "O fecho.", "Origem.", TI406, "Moldura da seção."]
MARCAS406_EN = [TW406E, "What enters.", "The frame: what closed and what enters.", "The Bridge of the Mass.", "Mass = pure tension.", "The law of the diminished.", "The Tonic of the Hamiltonian.", "The Zero Point of the Psion.", "Euler's Disk.", "Observer = terminal.", "The stone Identity.", "Errata alongside (v406).", "Limits.", "The closing.", "Origin.", TI406E, "Frame of the section."]
'''
_ASSERTS_NOVOS = r'''_vn = esp["vereditos_novos_v406"]
assert all(_vn[DL.REGISTRO_DE_PEDRA[s["key"]]].startswith("TGL_") and "__GATE_UNMOVED" in _vn[DL.REGISTRO_DE_PEDRA[s["key"]]] for s in DL.STONES), _vn
assert _vn["cunhagens_v405"].startswith("TGL_CUNHAGENS_V406__") and _vn["campos_fechados_e_leituras_v405"].startswith("TGL_CAMPOS_FECHADOS_E_LEITURAS_V405") and _vn["ga_reclassificacao_v405"].startswith("TGL_GA_RECLASSIFICACAO_V406__") and _vn["gap_v405"].startswith("TGL_GAP_V406__") and _vn["kh_n1_cobertura_v405"].startswith("TGL_KH_N1_COBERTURA_V406__"), _vn
assert sorted(esp["registros_v405"]) == ["campos_fechados_e_leituras_v405", "cunhagens_v405", "ga_reclassificacao_v405", "gap_v405", "kh_n1_cobertura_v405"] and sorted(esp["registros_v404"]) == ["cunhagens_v404", "kh_n1_cobertura_v404"] and sorted(esp["registros_v403"]) == ["cunhagens_v403", "kh_n1_cobertura_v403"] and sorted(esp["registros_v402"]) == ["cunhagens_v402", "kh_n1_cobertura_v402"] and sorted(esp["registros_v401"]) == ["cunhagens_v401", "kh_n1_cobertura_v401"]
_rf = esp["registros_funcao_v406"]
assert abs(_rf["ponte"]["values"]["m_derivada_meV"] / esp["m_nu_meV_v404"] - 1.0) <= 1e-12 and abs(_rf["psion"]["values"]["meia_hbar_omega_meV"] / esp["m_nu_meV_v404"] - 1.0) <= 1e-12 and abs(_rf["diminuto"]["values"]["E0_eV"] - 1.0) <= 1e-12, _rf
assert [_rf[k]["n_checks"] for k in DL.N_CHECKS] == [DL.N_CHECKS[k] for k in DL.N_CHECKS] and sorted(_rf) == sorted(DL.N_CHECKS), [(k, _rf[k]["n_checks"]) for k in _rf]
assert not any(GF.violacoes(v_) for v_ in _vn.values()), "um veredito novo afirma demais"
'''
